  const donorRecords = listDonorRepositories()
    .map((donor) => buildRecord(repoRoot, donor))
    .sort((a, b) => {
      const urgencyDiff = urgencyRank(a.urgency) - urgencyRank(b.urgency);
      if (urgencyDiff !== 0) {
        return urgencyDiff;
      }

