function scoreModules(text) {
  const lower = text.toLowerCase();
  const scores = modules.map(([name, terms]) => [name, terms.reduce((sum, term) => sum + (lower.includes(term) ? (term.includes(' ') ? 3 : 1) : 0), 0)]).filter(([,s]) => s > 0).sort((a,b) => b[1]-a[1]);
  return scores;
}

